# Erzeugt app/src/main/assets/hardcore_tasks.txt
# Format: code|kat|stufe|min|xp|koerperlich|gelenke|partner|toy|anatomie|rollen|sicherheit|titel|beschreibung
# Platzhalter: {min} = nichtkörperliche Dauer (skaliert mit Stufe), {toy} = Toy aus der Galerie
import sys

ROWS = []
SUB = "SUB,SWITCH,SOLO"
DOM = "DOM,SWITCH"
ALL = "SUB,SWITCH,SOLO,DOM"


def T(cat, d, title, desc, mins=0, xp=None, phys=0, joint=0, partner=0, toy="", anat="", roles=SUB, safe="A"):
    if xp is None:
        xp = 15 + d * 10 + (5 if partner else 0)
    ROWS.append((cat, d, mins, xp, phys, joint, partner, toy, anat, roles, safe, title, desc))


# ---------------- Dominanz und Unterwerfung ----------------
c = "hc_ds"
T(c, 1, "Erste Meldung", "Stell dich gerade hin. Hände auf den Rücken. Sag laut: „Ich bin bereit für meine Prüfung.“ Dann wartest du {min} Minuten schweigend auf mein Urteil.", 3)
T(c, 1, "Anredepflicht", "Ab jetzt sprichst du mich nur noch mit meiner Anrede an. Jeder Satz an mich beginnt damit. {min} Minuten lang, ohne Ausnahme.", 10)
T(c, 1, "Blick gesenkt", "Senk den Blick. {min} Minuten lang schaust du nicht nach oben, egal was passiert. Du schaust nur, wenn es für deine Sicherheit nötig ist.", 5)
T(c, 1, "Wartehaltung", "Stell dich in die Wartehaltung: Füße schulterbreit, Hände hinter dem Rücken, Kinn leicht gesenkt. {min} Minuten. Kein Zappeln.", 4, phys=1)
T(c, 2, "Kniende Meldung", "Auf die Knie. Hände flach auf die Oberschenkel, Blick zu Boden. Melde dich mit vollem Satz zur Prüfung und bleib {min} Minuten so. Kissen unter den Knien ist erlaubt.", 4, phys=1, joint=1)
T(c, 2, "Drei Regeln", "Sprich deine drei wichtigsten Regeln für heute laut aus. Dann wiederholst du sie, bis du sie fehlerfrei aufsagen kannst. Jeder Versprecher: von vorn.", 5)
T(c, 2, "Erlaubnis zu sitzen", "Du setzt dich die nächsten {min} Minuten nur, wenn du vorher laut um Erlaubnis gebeten hast. Ich erteile sie dir nach zehn langsamen Atemzügen.", 20)
T(c, 2, "Dienst am Dungeon", "Bereite deinen Spielbereich vor: aufgeräumt, Decke, Wasser, alles griffbereit. Du arbeitest schweigend. Danach meldest du dich kniend oder stehend fertig.", 15, phys=1)
T(c, 3, "Inspektionshaltung", "Inspektionshaltung: aufrecht stehen, Hände hinter dem Kopf verschränkt, Beine leicht gespreizt. {min} Minuten reglos. Ich inspiziere deine Haltung.", 4, phys=1)
T(c, 3, "Gehorsamsdrill", "Ich gebe dir fünf Kommandos im Wechsel: Stehen, Knien, Warten, Blick senken, Melden. Wechsle bei jedem Kommando ohne Zögern. Zehn Durchgänge. Bei Knieproblemen ersetzt du Knien durch tiefes Verbeugen.", 8, phys=1)
T(c, 3, "Schweigegelübde", "Du sprichst {min} Minuten kein einziges Wort. Nicht mit dir, nicht mit mir. Erlaubt ist nur dein Safeword.", 30)
T(c, 3, "Dankespflicht", "Für jede Anweisung, die du in dieser Session erhältst, bedankst du dich laut. Vergisst du es, beginnt die Prüfung von vorn. {min} Minuten.", 20)
T(c, 3, "Ritual der Unterwerfung", "Entwirf ein kurzes Begrüßungsritual für mich: Haltung, Worte, Geste. Führe es dreimal makellos aus. Ab jetzt ist es Pflicht bei jeder Session.", 10, phys=1)
T(c, 4, "Präsentation der Disziplin", "Wechsle zwischen Wartehaltung und Inspektionshaltung, jeweils zwei Minuten, insgesamt zwölf Minuten. Bei jedem Wechsel meldest du die Position mit vollem Satz.", 12, phys=1)
T(c, 4, "Bettle um die Prüfung", "Du bekommst deine nächste Prüfung nicht geschenkt. Bitte dreimal darum, jedes Mal mit anderen Worten und überzeugender. Erst dann darfst du weiter.", 5)
T(c, 4, "Regelbuch", "Lege fünf feste Verhaltensregeln für die kommenden {min} Minuten fest. Sprich sie laut aus und halte dich an jede einzelne. Ein Bruch, und die Prüfung ist nicht bestanden.", 45)
T(c, 4, "Dienstbote", "Bereite deiner Partnerperson ein Getränk zu und serviere es kniend oder mit tiefer Verbeugung. Warte danach schweigend, bis du entlassen wirst.", 10, partner=1, phys=1)
T(c, 4, "Befehlsempfang", "Deine Partnerperson gibt dir zehn Minuten lang kurze, harmlose Befehle aus eurer vereinbarten Liste. Jeder wird mit „Ja“ und der Anrede bestätigt und sofort ausgeführt.", 10, partner=1, phys=1)
T(c, 5, "Totale Kontrolle", "Für {min} Minuten fragst du für alles um Erlaubnis: aufstehen, trinken, sprechen, die Haltung ändern. Ohne Erlaubnis bewegst du dich nicht. Wasser trinken darfst du immer.", 30)
T(c, 5, "Der lange Gehorsam", "Kombiniere: Anredepflicht, gesenkter Blick und Dankespflicht – gleichzeitig, {min} Minuten lang. Ein einziger Fehler und du hast nicht bestanden.", 30)
T(c, 5, "Unterwerfungsschwur", "Formuliere einen Schwur, der deine Rolle in diesem Dungeon beschreibt. Sprich ihn kniend oder stehend dreimal aus, jedes Mal langsamer und deutlicher. Dann wartest du {min} Minuten in Stille.", 10, phys=1)
T(c, 5, "Zwei Herren dienen", "Deine Partnerperson und ich geben dir abwechselnd Anweisungen. Sie hat Vorrang. Fünfzehn Minuten Dienst, danach ein ehrlicher Bericht an sie.", 15, partner=1, phys=1)
T(c, 6, "Prüfung des absoluten Gehorsams", "Drei Runden: Inspektionshaltung, Regelaufsagen, Wartehaltung – je fünf Minuten. Zwischen den Runden bittest du um die Erlaubnis weiterzumachen. Kein Fehler erlaubt.", 15, phys=1)
T(c, 6, "Tag der Unterwerfung", "Für die nächsten {min} Minuten gilt dein komplettes Protokoll: Anrede, Erlaubnis, Dank, Blick gesenkt. Du bleibst dabei in Bewegung und trinkst regelmäßig. Ich erwarte Perfektion.", 90)
T(c, 6, "Eigentumserklärung", "Erkläre laut, wem du heute gehörst und was das bedeutet. Danach {min} Minuten in Wartehaltung mit Pausen nach Bedarf. Am Ende bedankst du dich für die Prüfung.", 20, phys=1)
T(c, 2, "Session leiten", "Du führst. Gib deiner Partnerperson fünf Minuten lang klare Haltungsbefehle aus eurer vereinbarten Liste. Achte auf ihr Befinden und frag am Ende nach.", 5, partner=1, roles=DOM)
T(c, 3, "Protokoll festlegen", "Lege mit deiner Partnerperson drei Protokollregeln für eure nächste Session fest und lass sie diese laut bestätigen. Beide sagen ihr Safeword einmal laut.", 10, partner=1, roles=DOM)
T(c, 4, "Inspektion durchführen", "Lass deine Partnerperson die Inspektionshaltung einnehmen und korrigiere sie wortlos mit Gesten. Fünf Minuten. Danach Aftercare und Rückmeldung.", 5, partner=1, roles=DOM, phys=1)
T(c, 5, "Herrschaft über die Zeit", "Deine Partnerperson darf {min} Minuten lang nichts ohne deine Erlaubnis tun. Du bleibst aufmerksam, sorgst für Wasser und beendest sofort bei Unwohlsein.", 30, partner=1, roles=DOM)
T(c, 1, "Bericht erstatten", "Erstatte mir mündlich Bericht: Was hast du heute für den Dungeon getan, was nicht? Zwei Minuten, keine Ausreden.", 3)

# ---------------- Humiliation ----------------
c = "hc_humiliation"
T(c, 1, "Das richtige Wort", "Sag laut: „Ich bin heute nur ein Spielzeug für diesen Dungeon.“ Fünfmal. Jedes Mal etwas lauter.", 2)
T(c, 1, "Dritte Person", "Du sprichst von dir {min} Minuten lang nur in der dritten Person, als „das Spielzeug“. Jeder Rückfall wird laut eingestanden.", 10)
T(c, 1, "Ecke", "Stell dich in die Ecke, Gesicht zur Wand, Hände auf dem Rücken. {min} Minuten. Denk darüber nach, warum du hier stehst.", 5, phys=1)
T(c, 2, "Geständnis", "Gestehe laut drei Dinge, bei denen du heute versagt hast. Danach bittest du um Verzeihung, in meiner Anrede.", 4)
T(c, 2, "Namensentzug", "Du hast {min} Minuten lang keinen Namen. Wenn du von dir sprichst, nennst du dich so, wie ich es bestimme: „Nichtsnutz“ oder ein Wort deiner Wahl, das in deinen Grenzen liegt.", 15)
T(c, 2, "Bettelrunde", "Bettle um die Erlaubnis, deine nächste Prüfung zu bekommen. Drei Sätze, jeder demütiger als der letzte. Ich entscheide, ob es reicht.", 3)
T(c, 2, "Verkehrte Ordnung", "Zieh ein Kleidungsstück verkehrt herum an und trag es zu Hause {min} Minuten lang. Nur in deinen vier Wänden, niemand sonst bekommt etwas mit.", 30)
T(c, 3, "Das Urteil", "Sprich dein eigenes Urteil: „Ich habe diese Prüfung nötig, weil …“. Ergänze ehrlich drei Gründe. Danach {min} Minuten in der Ecke.", 5, phys=1)
T(c, 3, "Lobverbot", "Du darfst dich {min} Minuten lang selbst nicht loben und nichts beschönigen. Jede Ausrede wird laut zurückgenommen.", 30)
T(c, 3, "Demütige Bitte", "Knie dich hin oder verbeuge dich tief und bitte darum, mir weiter dienen zu dürfen. Wiederhole die Bitte, bis sie wirklich ehrlich klingt.", 4, phys=1, joint=1)
T(c, 3, "Kosename des Tages", "Deine Partnerperson gibt dir für die heutige Session einen erniedrigenden Spitznamen aus eurer vereinbarten Liste. Du antwortest nur darauf. {min} Minuten.", 30, partner=1)
T(c, 3, "Erlaubnis zu sprechen", "Bevor du sprichst, hebst du die Hand und wartest fünf Atemzüge. Erst dann darfst du reden. {min} Minuten lang.", 20)
T(c, 4, "Die Liste der Schwächen", "Sprich zehn Dinge laut aus, die du an dir als Spielzeug verbessern musst. Ohne Pause zwischen den Punkten. Stockst du, beginnst du von vorn.", 6)
T(c, 4, "Ecke mit Geständnis", "Fünf Minuten in der Ecke. Jede Minute sagst du laut einen Satz, warum du dort stehst. Danach bedankst du dich für die Korrektur.", 5, phys=1)
T(c, 4, "Spielzeugstatus", "Für {min} Minuten bist du ein Gegenstand. Du sprichst nur, wenn du gefragt wirst, und antwortest mit einem Wort. Safeword gilt immer.", 30)
T(c, 4, "Vorführung", "Deine Partnerperson lässt dich die vereinbarte Haltung einnehmen und kommentiert sie spöttisch. Du bedankst dich nach jedem Kommentar. Zehn Minuten.", 10, partner=1, phys=1)
T(c, 5, "Doppelte Demütigung", "Kombiniere Dritte Person und Erlaubnis zu sprechen. {min} Minuten. Jeder Fehler wird laut gestanden.", 30)
T(c, 5, "Rede des Versagers", "Halte eine einminütige Rede darüber, warum du heute die Härte des Dungeons verdienst. Danach wartest du {min} Minuten schweigend auf mein Urteil.", 5)
T(c, 5, "Bitte um Härte", "Bitte dreimal ausdrücklich um eine strengere nächste Prüfung, jedes Mal mit Begründung. Wenn ich nicht überzeugt bin, war es nicht bestanden.", 4)
T(c, 5, "Gehorsamer Gegenstand", "Deine Partnerperson stellt dich wie ein Möbelstück in eine bequeme, sichere Haltung und ignoriert dich {min} Minuten. Du rührst dich nur bei Unwohlsein.", 10, partner=1, phys=1)
T(c, 6, "Völlige Erniedrigung", "Drei Stufen: Geständnis, Rede des Versagers, Ecke mit Geständnis. Ohne Unterbrechung. Zwischen den Stufen bittest du um die Erlaubnis weiterzumachen.", 15, phys=1)
T(c, 6, "Tag ohne Namen", "Für {min} Minuten gilt: kein Name, nur Dritte Person, Erlaubnis zu sprechen, Lobverbot. Du hältst durch oder du scheiterst.", 90)
T(c, 6, "Urteil der Herrschaft", "Deine Partnerperson spricht ein spöttisches Urteil über deine heutige Leistung. Du hörst kniend oder stehend zu, wiederholst es Wort für Wort und bedankst dich.", 10, partner=1, phys=1)
T(c, 2, "Spott dosieren", "Du bist dran: Necke deine Partnerperson fünf Minuten lang mit Spitznamen aus eurer vereinbarten Liste. Danach fragst du, wie es sich angefühlt hat.", 5, partner=1, roles=DOM)
T(c, 1, "Zugeben", "Gib laut zu, dass du diese Prüfung wolltest. Ein vollständiger Satz, ohne Lachen.", 1)
T(c, 4, "Strafbank", "Setz dich {min} Minuten auf den Boden in eine Ecke deines Zimmers. Kein Handy, keine Musik. Nur du und dein Versagen.", 15)

# ---------------- Chastity ----------------
c = "hc_chastity"
T(c, 1, "Keuschheitsschwur", "Sprich deinen Keuschheitsschwur laut: wie lange, warum, für wen. Danach startest du im Keuschheitstracker deine Periode – mit einem Ziel, das du allein festlegst.", 3)
T(c, 1, "Verschlusskontrolle", "Kontrolliere deinen Verschluss: Sitz, Haut, nichts drückt oder klemmt. Melde mir in einem Satz den Zustand.", 3, toy="Keuschheitszubehör", safe="B")
T(c, 1, "Gedankenkeuschheit", "Für {min} Minuten verbiete ich dir jede erotische Ablenkung: keine Bilder, keine Videos, keine Berührungen. Du wartest.", 30)
T(c, 2, "Schlüsselzeremonie", "Lege den Schlüssel sichtbar an einen festen Ort, den du nur mit Erlaubnis berührst. Der Notfallschlüssel bleibt jederzeit erreichbar. Sprich deinen Schwur.", 5, toy="Keuschheitszubehör", safe="B")
T(c, 2, "Verschlossen dienen", "Verschlossen räumst du {min} Minuten lang deinen Wohnbereich auf. Bei jedem Druckgefühl: sofort prüfen.", 15, toy="Keuschheitszubehör", phys=1, safe="B")
T(c, 2, "Keyholder-Meldung", "Melde dich bei deiner Partnerperson als Keyholder: Zustand, Gefühl, Wunsch. Sie entscheidet über die nächste Aufgabe, nicht über deine Gesundheit.", 5, partner=1)
T(c, 2, "Hygienepflicht", "Hygienekontrolle nach Plan: reinigen, Haut prüfen, gut abtrocknen. Wenn nötig, Verschluss sofort öffnen und pausieren. Danach meldest du dich zurück.", 10, toy="Keuschheitszubehör", safe="B")
T(c, 3, "Keuschheit unter Prüfung", "Verschlossen nimmst du {min} Minuten lang die Wartehaltung ein und denkst an nichts anderes als an deinen Verschluss.", 5, toy="Keuschheitszubehör", phys=1, safe="B")
T(c, 3, "Versuchung widerstehen", "Lies {min} Minuten lang etwas, das dich reizt, ohne dich zu berühren. Danach meldest du, wie stark du warst.", 10)
T(c, 3, "Bitte um Aufschluss", "Bitte deine Partnerperson förmlich um eine Pause vom Verschluss. Sie darf ablehnen – außer bei Beschwerden, dann wird sofort aufgeschlossen.", 5, partner=1, toy="Keuschheitszubehör", safe="B")
T(c, 3, "Keuschheitsbericht", "Erstatte mir Bericht: Wie lange bist du schon keusch, was fällt dir schwer, was willst du erreichen? Danach einen Eintrag ins Tagebuch.", 5)
T(c, 4, "Verschlossene Disziplin", "Verschlossen: Anredepflicht und gesenkter Blick für {min} Minuten. Dein Verschluss erinnert dich an jede Regel.", 20, toy="Keuschheitszubehör", safe="B")
T(c, 4, "Versuchung zu zweit", "Deine Partnerperson neckt dich fünf Minuten lang mit Worten, während du verschlossen bleibst. Du bedankst dich am Ende für die Prüfung.", 5, partner=1, toy="Keuschheitszubehör", safe="B")
T(c, 4, "Ziel bestätigen", "Prüfe dein aktuelles Keuschheitsziel im Tracker. Sprich laut aus, ob du es halten willst. Verlängern darfst nur du selbst, und nur wenn es dir gut geht.", 3)
T(c, 4, "Der Schlüssel wartet", "Lass den Schlüssel bis zum Ende dieser Prüfung liegen: {min} Minuten. Der Notfallschlüssel bleibt griffbereit.", 60, toy="Keuschheitszubehör", safe="B")
T(c, 5, "Keuschheitsserie", "Verschlusskontrolle, Schwur, dann {min} Minuten Gedankenkeuschheit. In dieser Reihenfolge, ohne Abkürzung.", 30, toy="Keuschheitszubehör", safe="B")
T(c, 5, "Keyholder-Verhör", "Deine Partnerperson befragt dich fünf Minuten lang zu deinen Gedanken und Wünschen. Du antwortest ehrlich und mit Anrede. Lügen heißt: nicht bestanden.", 5, partner=1)
T(c, 5, "Versprechen der Enthaltung", "Versprich laut, bis morgen früh auf jeden Höhepunkt zu verzichten. Trag es als Notiz in den Keuschheitstracker ein.", 3)
T(c, 6, "Eiserne Keuschheit", "Verschlusskontrolle, Verschlossen dienen, Versuchung widerstehen – alles hintereinander. Danach Bericht.", 30, toy="Keuschheitszubehör", phys=1, safe="B")
T(c, 6, "Albtraum der Enthaltung", "Für {min} Minuten gilt: keine erotischen Gedanken pflegen, keine Berührung, Anredepflicht. Wenn es dir schlecht geht, brich ab – das zählt nicht gegen dich.", 120)
T(c, 6, "Keyholder-Urteil", "Deine Partnerperson entscheidet über deine nächste Keuschheitsprüfung aus eurer vereinbarten Liste. Du nimmst das Urteil kniend oder stehend an.", 5, partner=1, phys=1)
T(c, 1, "Startschuss", "Noch nicht verschlossen? Dann setz dir jetzt ein kleines Keuschheitsziel im Tracker. Klein ist erlaubt. Kneifen ist es nicht.", 2)
T(c, 3, "Schlüsselhüter sein", "Du verwahrst den Schlüssel deiner Partnerperson. Kontrolliere zweimal am Tag ihr Befinden und gib ihn sofort heraus, wenn sie danach fragt.", 5, partner=1, roles=DOM)
T(c, 2, "Sieben Atemzüge", "Jedes Mal, wenn du in den nächsten {min} Minuten an Erlösung denkst, machst du sieben ruhige Atemzüge und sagst laut: „Nicht jetzt.“", 30)

# ---------------- Orgasm Control ----------------
