T(c, 5, "Countdown-Folter", "Berühre dich nur während der letzten fünf Sekunden jeder Minute. Zehn Minuten lang. Kein Höhepunkt.", 10, phys=1, safe="B")
T(c, 6, "Sechs Kanten", "Sechs Kanten, nach jeder dreißig Sekunden Haltung und ein Satz der Unterwerfung. Kein Höhepunkt. Trink danach Wasser.", 25, phys=1, safe="B")
T(c, 6, "Albtraum der Erlaubnis", "Kanten-Serie: zwei, Pause, zwei, Pause, zwei. Nach jeder Serie bittest du. Ich lehne ab. Am Ende {min} Minuten Verzicht.", 25, phys=1, safe="B")
T(c, 6, "Der lange Verzicht", "Kein Höhepunkt für {min} Minuten. Jede Stunde eine Kante, bei Unwohlsein sofort Pause. Das Gelübde sprichst du jetzt laut.", 180, safe="B")
T(c, 3, "Erlaubnis erteilen", "Du kontrollierst: Deine Partnerperson darf nur mit deiner ausdrücklichen Erlaubnis kommen. Achte auf ihr Befinden und hör auf, wenn sie Stopp sagt.", 15, partner=1, roles=DOM, safe="B")
T(c, 1, "Hände weg", "Die nächsten {min} Minuten berührst du dich nicht. Kein Test, kein Versehen.", 20)
T(c, 5, "Toy-Leiter", "{toy}: drei Kanten mit steigender Dauer – eine, zwei, drei Minuten. Kein Höhepunkt. Danach wegräumen und Bericht.", 15, phys=1, toy="Dildos", safe="C")

