def main(path):
    lines = ["# code|kat|stufe|min|xp|koerperlich|gelenke|partner|toy|anatomie|rollen|sicherheit|titel|beschreibung"]
    titles = set()
    for i, r in enumerate(ROWS, 1):
        cat, d, mins, xp, phys, joint, partner, toy, anat, roles, safe, title, desc = r
        key = (cat, title)
        assert key not in titles, key
        titles.add(key)
        code = "HC-%03d" % i
        lines.append("|".join(str(x) for x in [code, cat, d, mins, xp, phys, joint, partner, toy, anat, roles, safe, title, desc]))
    open(path, "w", encoding="utf-8").write("\n".join(lines) + "\n")
    from collections import Counter
    print(len(ROWS), Counter(r[0] for r in ROWS), Counter(r[1] for r in ROWS))


main(sys.argv[1])
